<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\Payment;use App\Services\Commerce\{PaystackService,PaymentFinalizer};use Illuminate\Http\{JsonResponse,Request};class PaystackWebhookController extends Controller{public function __invoke(Request$r,PaystackService$p,PaymentFinalizer$f):JsonResponse{$s=(string)config('services.paystack.secret_key');if($s===''||!hash_equals(hash_hmac('sha512',$r->getContent(),$s),(string)$r->header('x-paystack-signature','')))return response()->json(['ok'=>false],$s===''?500:401);$d=$r->json()->all();$ref=(string)($d['data']['reference']??'');if(($d['event']??'')!=='charge.success'||$ref===''||!Payment::where('reference',$ref)->exists())return response()->json(['ok'=>true]);$f->finalizePaystack($ref,$p->verify($ref));return response()->json(['ok'=>true]);}}